  updated_at timestamptz not null default now()
);
create or replace function public.validate_family_settings() returns trigger language plpgsql set search_path = '' as $$
begin
  if not exists (select 1 from pg_timezone_names where name = new.timezone) then
    raise exception 'Choose a valid time zone';
  end if;
  new.updated_at := now();
  return new;
end $$;
drop trigger if exists validate_family_settings on public.family_settings;
create trigger validate_family_settings before insert or update on public.family_settings for each row execute function public.validate_family_settings();
insert into public.family_settings(parent_id) select id from auth.users on conflict do nothing;
create or replace function public.initialize_family_settings() returns trigger language plpgsql security definer set search_path = '' as $$
